#ifndef NORTH_ISLAND_CLIENT_SERVICES_EMBEDDED_LAYOUTS_H
#define NORTH_ISLAND_CLIENT_SERVICES_EMBEDDED_LAYOUTS_H

#include <optional>
#include <string>

namespace client {

    /// @brief Looks up a screen layout compiled into the program (table generated by cmake/EmbedLayouts.cmake).
    /// @param fileName Bare layout file name, e.g. "LoginForm.xml".
    /// @return The layout text, or nothing when there is no layout of that name.
    std::optional<std::string> embeddedLayout(const std::string& fileName);

}

#endif
